import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    t = int(next(iterator))

    results = []

    for _ in range(t):
        n = int(next(iterator))
        a = []
        for _ in range(n):
            a.append(int(next(iterator)))

        # dp[i][0] = min skip points when it's Friend's turn at index i
        # dp[i][1] = min skip points when it's Your turn at index i

        INF = float('inf')
        dp = [[INF, INF] for _ in range(n + 1)]
        dp[0][0] = 0  # Start with Friend's turn at index 0

        for i in range(n):
            # From state where it's Friend's turn at i
            if dp[i][0] != INF:
                # Friend kills 1 boss
                cost1 = dp[i][0] + a[i]
                if cost1 < dp[i+1][1]:
                    dp[i+1][1] = cost1

                # Friend kills 2 bosses
                if i + 2 <= n:
                    cost2 = dp[i][0] + a[i] + a[i+1]
                    if cost2 < dp[i+2][1]:
                        dp[i+2][1] = cost2

            # From state where it's Your turn at i
            if dp[i][1] != INF:
                # You kill 1 boss (no cost for friend)
                if dp[i][1] < dp[i+1][0]:
                    dp[i+1][0] = dp[i][1]

                # You kill 2 bosses
                if i + 2 <= n:
                    if dp[i][1] < dp[i+2][0]:
                        dp[i+2][0] = dp[i][1]

        results.append(str(dp[n][0]))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == '__main__':
    solve()
